import { writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import ts from 'typescript'

/**
 * Where a JSDoc line of a generated file wraps: the column limit less the
 * ` * ` gutter.
 */
const DOC_WIDTH = 77

/**
 * The three tables, each named for the `SyntaxKind` range it is sliced
 * from; see string-predicate.spec.md.
 */
const TABLES = Object.freeze([
  {
    file: 'reserved-words.ts',
    name: 'RESERVED_WORDS',
    range: 'ReservedWord',
    summary: "TypeScript's ReservedWord range: never an identifier.",
  },
  {
    file: 'strict-mode-reserved-words.ts',
    name: 'STRICT_MODE_RESERVED_WORDS',
    range: 'FutureReservedWord',
    summary:
      "TypeScript's FutureReservedWord range: reserved in strict mode code.",
  },
  {
    file: 'contextual-keywords.ts',
    name: 'CONTEXTUAL_KEYWORDS',
    range: 'ContextualKeyword',
    summary:
      "TypeScript's ContextualKeyword range: keywords that remain legal" +
      ' identifiers.',
  },
])

/**
 * Prose as JSDoc lines, broken greedily at spaces within the width.
 */
const docLines = text =>
  text
    .split(' ')
    .reduce(
      (lines, word) =>
        lines.length > 0 &&
        `${lines[lines.length - 1]} ${word}`.length <= DOC_WIDTH
          ? [...lines.slice(0, -1), `${lines[lines.length - 1]} ${word}`]
          : [...lines, word],
      [],
    )
    .map(line => ` * ${line}`)
    .join('\n')

/**
 * One `SyntaxKind` range's keywords, sorted, from the installed
 * TypeScript's keyword table.
 */
const keywordsOf = (range, api = ts) =>
  [
    ...Object.entries(api.textToKeywordObj)
      .filter(
        ([, kind]) =>
          kind >= api.SyntaxKind[`First${range}`] &&
          kind <= api.SyntaxKind[`Last${range}`],
      )
      .map(([text]) => text),
  ].sort()

/**
 * One generated file: the table as a `ReadonlySet`, its JSDoc carrying the
 * summary and the generation note.
 */
export const renderReservedWords = (table, api = ts) => `/**
 * ${table.summary}
 *
${docLines(
  'Generated by scripts/gen-reserved-words.mjs from TypeScript' +
    ` ${api.version}; not edited by hand. reserved.test.ts fails when this` +
    ' table drifts from the installed TypeScript.',
)}
 */
export const ${table.name}: ReadonlySet<string> = new Set([
${keywordsOf(table.range, api)
  .map(word => `  '${word}',`)
  .join('\n')}
])
`

if (
  process.argv[1] &&
  resolve(process.argv[1]) === new URL(import.meta.url).pathname
) {
  const dir = resolve(process.argv[2] ?? 'src/string-predicate/reserved')

  for (const table of TABLES) {
    const target = resolve(dir, table.file)
    writeFileSync(target, renderReservedWords(table))
    console.log(`wrote ${target}`)
  }
}
